def check(candidate):
    import sys

    counter = {"append_calls": 0}

    def profiler(frame, event, arg):
        if event == "c_call":
            name = getattr(arg, "__name__", None)
            objcls = getattr(arg, "__objclass__", None)
            if name == "append" and objcls is list:
                counter["append_calls"] += 1

    old = sys.getprofile()
    sys.setprofile(profiler)
    try:
        out = candidate("a")
    finally:
        sys.setprofile(old)

    assert (out, counter["append_calls"]) == ("2", 26)

